import {
  broadcastId,
  cancelledId,
  collectionId,
  draftId,
  postalAddress,
  purposeId,
  reuseIdentity,
  testId,
  workspace,
} from "./cli-production-broadcast-responses.mjs";

export function draftCreateArguments(extra) {
  return [
    "broadcast",
    "draft",
    "create",
    "--workspace",
    workspace,
    "--environment",
    "production",
    "--idempotency-key",
    draftId,
    "--title",
    "Synthetic product update",
    "--subject",
    "August update",
    "--body",
    "<p>Hello synthetic subscribers</p>",
    "--preheader",
    "Synthetic preheader",
    "--sender-profile-id",
    "sender-profile-v1",
    "--communication-purpose-id",
    purposeId,
    "--include-collection",
    collectionId,
    ...(extra ? [extra] : []),
  ];
}

export function productionJourneyArguments() {
  return [
    [
      "broadcast",
      "audience",
      "options",
      "--workspace",
      workspace,
      "--environment",
      "production",
      "--json",
    ],
    draftCreateArguments("--json"),
    [
      "broadcast",
      "draft",
      "read",
      "--workspace",
      workspace,
      "--environment",
      "production",
      "--draft-id",
      draftId,
      "--json",
    ],
    [
      "broadcast",
      "audience",
      "preview",
      "--workspace",
      workspace,
      "--environment",
      "production",
      "--draft-id",
      draftId,
      "--json",
    ],
    [
      "broadcast",
      "test",
      "send",
      "--workspace",
      workspace,
      "--environment",
      "production",
      "--draft-id",
      draftId,
      "--revision",
      "1",
      "--postal-address",
      postalAddress,
      "--idempotency-key",
      "test-once",
      "--json",
    ],
    [
      "broadcast",
      "test",
      "status",
      "--workspace",
      workspace,
      "--environment",
      "production",
      "--draft-id",
      draftId,
      "--test-id",
      testId,
      "--watch",
      "--json",
    ],
    preflightArguments(),
    [
      "broadcast",
      "authorize",
      "--workspace",
      workspace,
      "--environment",
      "production",
      "--draft-id",
      draftId,
      "--revision",
      "1",
      "--postal-address",
      postalAddress,
      "--idempotency-key",
      "authorize-once",
      "--acknowledge-audience-reuse",
      reuseIdentity,
      "--json",
    ],
    controlArguments("pause", broadcastId),
    controlArguments("resume", broadcastId),
    [
      "broadcast",
      "status",
      "--workspace",
      workspace,
      "--environment",
      "production",
      "--broadcast-id",
      broadcastId,
      "--watch",
      "--json",
    ],
    controlArguments("cancel", cancelledId),
    [
      "broadcast",
      "result",
      "--workspace",
      workspace,
      "--environment",
      "production",
      "--broadcast-id",
      broadcastId,
      "--json",
    ],
  ];
}

export function preflightArguments() {
  return [
    "broadcast",
    "preflight",
    "--workspace",
    workspace,
    "--environment",
    "production",
    "--draft-id",
    draftId,
    "--expected-version",
    "1",
    "--postal-address",
    postalAddress,
    "--acknowledge-audience-reuse",
    reuseIdentity,
    "--json",
  ];
}

function controlArguments(operation, id) {
  return [
    "broadcast",
    operation,
    "--workspace",
    workspace,
    "--environment",
    "production",
    "--broadcast-id",
    id,
    "--json",
  ];
}
